/// <reference path="./sigApi.ApiBase.d.ts" />
/// <reference path="./sigApi.Font.d.ts" />

declare namespace SigApi {
    interface ApiFontManager extends ApiBase {
        /**
         * Gets a Font
         * 
         * @param {number|string} findParam `number`->fontIndex, `string`->fontName
         * 
         * @returns {Font} the requested Font
         */
        getFont(findParam: number | string): Font | null
        /**
         * Function to check if parameter object is a instanceof Font.
         * This function can be used without importing the type Font to be used with the instanceof operator.
         * @param {*} object Any object to type check
         * @returns {boolean} Returns true if parameter object is instanceof Font, else false
         */
        instanceofFont(object: any): boolean
    }
}
